%% Crear archivos open-loop de pitch para validar MPC en OpenFAST
% Caso turbulento 16 m/s
% Genera:
%   1) OL_pitch_BASE_turb.dat  -> pitch base sin MPC
%   2) OL_pitch_MPC_turb.dat   -> pitch base + corrección IPC del MPC

clear; clc;

rootDir = fullfile(getenv('USERPROFILE'), 'Desktop', 'TFM_OpenFast');

toolboxDir = fullfile(rootDir, 'Matlab', 'Matlab_Toolbox');
addpath(genpath(toolboxDir));

%% Rutas

caseModelDir = fullfile(rootDir, 'Modelo', 'CasoB_v16_turbulento', ...
    'IEA-15-240-RWT-UMaineSemi');

% Archivo donde se guardarán los open-loop pitch
fileOL_base = fullfile(caseModelDir, 'OL_pitch_BASE_turb.dat');
fileOL_mpc  = fullfile(caseModelDir, 'OL_pitch_MPC_turb.dat');

% CSV generado en la prueba offline del MPC
mpcCSV = fullfile(rootDir, 'Resultados', 'MPC_IPC', 'Offline', ...
    'mpc_offline_Base_turbulento.csv');

%% Buscar archivo .outb del caso base turbulento

candidates = {
    fullfile(rootDir, 'Resultados', 'CasoB_v16_turbulento', ...
    'IEA-15-240-RWT-UMaineSemi.outb')

    fullfile(rootDir, 'Modelo', 'CasoB_v16_turbulento', ...
    'IEA-15-240-RWT-UMaineSemi', 'IEA-15-240-RWT-UMaineSemi.outb')
};

baseOutb = "";

for i = 1:numel(candidates)
    if isfile(candidates{i})
        baseOutb = string(candidates{i});
        break;
    end
end

if baseOutb == ""
    error("No encuentro el .outb base turbulento. Ajusta manualmente la ruta baseOutb.");
end

fprintf("Leyendo base outb:\n%s\n", baseOutb); %[output:92b02d01]

%% Leer caso base

[X, ChanName, ChanUnit] = ReadFASTbinary(char(baseOutb)); %[output:32002538]

names = cleanNames(ChanName);
units = cleanNames(ChanUnit);

t = getChan(X, names, "Time");

BldPitch1 = getChan(X, names, "BldPitch1");
BldPitch2 = getChan(X, names, "BldPitch2");
BldPitch3 = getChan(X, names, "BldPitch3");

%% Comprobar unidades de pitch

idxPitch = find(strcmpi(names, "BldPitch1"), 1);
pitchUnit = lower(string(units(idxPitch)));

if contains(pitchUnit, "rad")
    pitch1_deg = rad2deg(BldPitch1);
    pitch2_deg = rad2deg(BldPitch2);
    pitch3_deg = rad2deg(BldPitch3);
else
    pitch1_deg = BldPitch1;
    pitch2_deg = BldPitch2;
    pitch3_deg = BldPitch3;
end

%% Leer correcciones MPC offline

if ~isfile(mpcCSV)
    error("No encuentro el CSV offline del MPC: %s", mpcCSV);
end

Tmpc = readtable(mpcCSV);

tTrans = 500; % el MPC offline se calculó después del transitorio

tMPC_full = Tmpc.TimeUseful_s + tTrans;

betaIPC1 = interp1(tMPC_full, Tmpc.BetaIPC1_deg, t, 'linear', 0);
betaIPC2 = interp1(tMPC_full, Tmpc.BetaIPC2_deg, t, 'linear', 0);
betaIPC3 = interp1(tMPC_full, Tmpc.BetaIPC3_deg, t, 'linear', 0);

%% Pitch total: base + corrección MPC

pitch1_base_rad = deg2rad(pitch1_deg);
pitch2_base_rad = deg2rad(pitch2_deg);
pitch3_base_rad = deg2rad(pitch3_deg);

pitch1_mpc_rad = deg2rad(pitch1_deg + betaIPC1);
pitch2_mpc_rad = deg2rad(pitch2_deg + betaIPC2);
pitch3_mpc_rad = deg2rad(pitch3_deg + betaIPC3);

%% Crear matrices open-loop
% Columnas:
% 1: Time [s]
% 2: BldPitch1 [rad]
% 3: BldPitch2 [rad]
% 4: BldPitch3 [rad]

OL_base = [t, pitch1_base_rad, pitch2_base_rad, pitch3_base_rad];
OL_mpc  = [t, pitch1_mpc_rad,  pitch2_mpc_rad,  pitch3_mpc_rad];

%% Escribir archivos sin cabecera

writeOpenLoopFile(fileOL_base, OL_base);
writeOpenLoopFile(fileOL_mpc, OL_mpc);

fprintf("\nArchivos creados:\n"); %[output:1ee17218]
fprintf("%s\n", fileOL_base); %[output:842d9851]
fprintf("%s\n", fileOL_mpc); %[output:2949854d]

%% Comprobaciones rápidas

fprintf("\nPitch base medio [deg]: %.3f %.3f %.3f\n", ... %[output:group:85c63c8b] %[output:71496a65]
    mean(pitch1_deg), mean(pitch2_deg), mean(pitch3_deg)); %[output:group:85c63c8b] %[output:71496a65]

fprintf("Corrección MPC máxima [deg]: %.3f %.3f %.3f\n", ... %[output:group:4563edc9] %[output:7495971d]
    max(abs(betaIPC1)), max(abs(betaIPC2)), max(abs(betaIPC3))); %[output:group:4563edc9] %[output:7495971d]

fprintf("Pitch total MPC máximo [deg]: %.3f %.3f %.3f\n", ... %[output:group:220e3da6] %[output:63d83491]
    max(abs(rad2deg(pitch1_mpc_rad))), ... %[output:63d83491]
    max(abs(rad2deg(pitch2_mpc_rad))), ... %[output:63d83491]
    max(abs(rad2deg(pitch3_mpc_rad)))); %[output:group:220e3da6] %[output:63d83491]

figure; %[output:7d8e39fb]
idxZoom = t >= 500 & t <= 560;
hold on; grid on; %[output:7d8e39fb]
plot(t(idxZoom), betaIPC1(idxZoom), 'DisplayName','\beta_{IPC,1}'); %[output:7d8e39fb]
plot(t(idxZoom), betaIPC2(idxZoom), 'DisplayName','\beta_{IPC,2}'); %[output:7d8e39fb]
plot(t(idxZoom), betaIPC3(idxZoom), 'DisplayName','\beta_{IPC,3}'); %[output:7d8e39fb]
xlabel('Tiempo [s]'); %[output:7d8e39fb]
ylabel('Corrección MPC [deg]'); %[output:7d8e39fb]
title('Corrección MPC que se enviará a OpenFAST'); %[output:7d8e39fb]
legend('Location','best'); %[output:7d8e39fb]

%% Funciones auxiliares

function names = cleanNames(raw)

    if ischar(raw)
        names = string(cellstr(raw));
    elseif isstring(raw)
        names = raw(:);
    elseif iscell(raw)
        names = strings(numel(raw),1);

        for i = 1:numel(raw)
            item = raw{i};

            if iscell(item)
                item = item{1};
            end

            names(i) = string(item);
        end
    else
        error("Formato de nombres no reconocido.");
    end

    names = strtrim(names(:));
end

function y = getChan(X, names, name)

    idx = find(strcmpi(names, name), 1);

    if isempty(idx)
        error("No encuentro el canal: %s", name);
    end

    y = X(:,idx);
end

function writeOpenLoopFile(filename, M)

    fid = fopen(filename, 'w');

    if fid < 0
        error("No se pudo abrir el archivo para escribir: %s", filename);
    end

    for i = 1:size(M,1)
        fprintf(fid, '%.6f %.10e %.10e %.10e\n', ...
            M(i,1), M(i,2), M(i,3), M(i,4));
    end

    fclose(fid);
end

